def generate(variables, templates_path, main_template):
    env = jinja2.Environment(
        loader=jinja2.FileSystemLoader(templates_path),
        lstrip_blocks=True,
        trim_blocks=True
    )
    def norm_alg_filename(alg_name):
        if alg_name in variables['globals']['algorithm_filename_parts']:
            return variables['globals']['algorithm_filename_parts'][alg_name]
        else:
            raise KeyError("{0} not found in globals.algorithm_filename_parts"
                           .format(alg_name))
    env.globals.update(norm_alg_filename=norm_alg_filename)
    template = env.from_string(main_template)
    return template.render(variables) + "\n"

def validate(self, instance, value):
        if isinstance(value, string_types) and self.mode is not None:
            try:
                value = open(value, self.mode)
            except (IOError, TypeError):
                self.error(instance, value,
                           extra='Cannot open file: {}'.format(value))
        if not all([hasattr(value, attr) for attr in ('read', 'seek')]):
            self.error(instance, value, extra='Not a file-like object')
        if not hasattr(value, 'mode') or self.valid_modes is None:
            pass
        elif value.mode not in self.valid_modes:
            self.error(instance, value,
                       extra='Invalid mode: {}'.format(value.mode))
        if getattr(value, 'closed', False):
            self.error(instance, value, extra='File is closed.')
        return value

