def get_dvcs_info():
    cmd = "git rev-list --count HEAD"
    commit_count = str(
        int(subprocess.check_output(shlex.split(cmd)).decode("utf8").strip())
    )
    cmd = "git rev-parse HEAD"
    commit = str(subprocess.check_output(shlex.split(cmd)).decode("utf8").strip())
    return {Constants.COMMIT_FIELD: commit, Constants.COMMIT_COUNT_FIELD: commit_count}

def system_model():
    mdata = {}
    man = None
    pn = None
    try:
        # This might be
        # sys_vendor, bios_vendor, board_vendor, or chassis_vendor
        man = open('/sys/class/dmi/id/sys_vendor').read().strip()
    except:
        if os.getuid() == 0:
            for line in os.popen('/usr/sbin/dmidecode -s system-manufacturer'):
                man = line.strip()
    try:
        pn = open('/sys/class/dmi/id/product_name').read().strip()
    except:
        if os.getuid() == 0:
            for line in os.popen('/usr/sbin/dmidecode -s system-product-name'):
                pn = line.strip()
    if man is not None:
        mdata['System_manufacturer'] = man
    if pn is not None:
        mdata['System_product_name'] = pn
    return mdata

def get_rev_options(url, rev):
    if rev:
        rev_options = ['-r', rev]
    else:
        rev_options = []
    r = urlparse.urlsplit(url)
    if hasattr(r, 'username'):
        # >= Python-2.5
        username, password = r.username, r.password
    else:
        netloc = r[1]
        if '@' in netloc:
            auth = netloc.split('@')[0]
            if ':' in auth:
                username, password = auth.split(':', 1)
            else:
                username, password = auth, None
        else:
            username, password = None, None
    if username:
        rev_options += ['--username', username]
    if password:
        rev_options += ['--password', password]
    return rev_options

